package com.jb.radar;
import android.graphics.*;import android.content.SharedPreferences;import javax.imageio.ImageIO;import java.io.File;
public class EconomyRenderCheck {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static void draw(MainActivity.Radar v,String n)throws Exception{v.last=0;Canvas c=new Canvas();v.onDraw(c);ImageIO.write(c.image,"png",new File("out/"+n+".png"));}
 public static void main(String[] a)throws Exception{MainActivity app=new MainActivity();app.getPreferences(0).edit().putInt("hawk_best",9999).commit();app.onCreate(null);app.onResume();MainActivity.Radar v=app.view;draw(v,"economy-menu-new-v07");v.act("start");for(Game.Contact t:v.game.contacts)v.game.confirmIntercept(t,false);Game.EnemyMissile m=new Game.EnemyMissile();m.id=101;m.weapon=4;v.game.enemyMissiles.add(m);v.game.confirmIntercept(m,true);v.game.finish(true);long total=v.economy.snapshot().dollars;draw(v,"rewards-v07");draw(v,"rewards-v07");check(v.economy.snapshot().dollars==total,"render cannot repay");v.act("menu");draw(v,"economy-menu-v07");v.act("economy");draw(v,"economy-v07");check(app.menuMusic.isPlaying(),"menu music on economy page");app.onPause();app.onDestroy();app=new MainActivity();app.onCreate(null);app.onResume();v=app.view;check(v.economy.snapshot().dollars==total&&v.best==9999,"wallet and old best survive recreation");v.act("start");Game.Contact t=v.game.contacts.get(0);SharedPreferences.failWrites=true;v.game.confirmIntercept(t,true);check(v.economy.saveFailed,"adapter commit failure signaled");v.act("menu");v.act("economy");draw(v,"economy-save-retry-v07");SharedPreferences.failWrites=false;v.act("retrysave");check(!v.economy.saveFailed,"retry through UI");Economy fresh=new Economy(new EconomyStore(app.getPreferences(0)));check(fresh.snapshot().dollars==total+250,"saved exactly once after retry");app.onPause();app.onDestroy();System.out.println("PASS: economy menu/results layout, no redraw payout, preference persistence, legacy best score, failed-save UI and retry");}
}
